import {categories,nearby,Picker,parseCoordinates,normalize,validPoint,fixAddressQuery,hasCjk,classify} from './core.mjs';
const $=id=>document.getElementById(id),picker=new Picker();let data,landmarks=[],center=null,selected=new Set(),lists=new Set(),matches=[],visible=24,searchVersion=0,geoVersion=0,searchController,lastSearch=0;const searchCache=new Map();
const e=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const distanceLabel=km=>km<1?`${Math.round(km*1000)} 公尺`:`${km.toFixed(1)} 公里`;
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error)}
function mapsLink(p,nav=false){return nav?`https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lon}&travelmode=walking`:p.url}
function link(text,url){const a=e('a','maplink',text);a.href=url;a.target='_blank';a.rel='noopener';return a}
function categoryNames(p){return p.categories.map(c=>categories[c]).filter(Boolean).join(' · ')}
function card(p){const article=e('article','card');const body=e('div','cardbody');const meta=e('div','category',categoryNames(p));const name=e('h3','',p.name);const address=e('p','address',p.address);const dist=e('div','distance',`${distanceLabel(p.distance)} · 直線距離`);const footer=e('div','cardfooter');footer.append(e('span','saved',`♡ ${p.list||'你的收藏'}`),link('Google Maps ↗',mapsLink(p)));body.append(meta,name,dist,address,footer);article.append(body);return article}
function syncCategoryButtons(){document.querySelectorAll('#categories .category-btn').forEach(t=>t.setAttribute('aria-pressed',String(t.dataset.category==='all'?!selected.size:selected.has(t.dataset.category))))}
function renderCards(){const list=matches.slice(0,visible);$('results').replaceChildren(...list.map(card));$('more').hidden=visible>=matches.length;$('more').textContent=`再顯示 ${Math.min(24,matches.length-visible)} 家`}
function render(){picker.reset();$('decision').hidden=true;visible=24;matches=nearby(data.places,center,Number($('radius').value),[...selected],[...lists]);const catLabel=selected.size?[...selected].map(k=>categories[k]).join('、'):categories.all;$('pick').disabled=!matches.length;$('pick').textContent='幫我決定一家 ↝';$('count').textContent=center?`${matches.length} 家符合條件 · ${catLabel} · 直線 ${$('radius').selectedOptions[0].textContent}內`:'先選擇地點，就能找到附近的口袋名單';$('results-title').textContent=center?`${center.name}附近`:'這一餐，從哪裡出發？';$('result-status').textContent=center?`找到 ${matches.length} 家符合條件的收藏。`:'';if(!center){$('results').replaceChildren(e('div','empty','輸入附近地標，或點「使用目前位置」。\n你的收藏已經準備好了。'));$('more').hidden=true;return}if(!matches.length){const empty=e('div','empty',selected.size===1&&selected.has('uncategorized')?'附近沒有待分類收藏。':'這個範圍沒有符合分類的店家。');const btn=e('button','secondary','擴大範圍');btn.type='button';btn.onclick=()=>{const opts=[...$('radius').options];const next=opts.find(o=>Number(o.value)>Number($('radius').value));if(next){$('radius').value=next.value;render()}else status('已是最大 50 公里範圍，可以換個地點或分類。')};empty.append(e('br'),btn);$('results').replaceChildren(empty);$('more').hidden=true;return}renderCards()}
function selectCenter(p){if(!validPoint(p))return;searchVersion++;geoVersion++;searchController?.abort();$('geo').disabled=false;$('geo').textContent='◎ 使用目前位置';$('find').disabled=false;center=p;$('location').value=p.name;$('suggestions').replaceChildren();$('suggestions').hidden=true;$('center-label').textContent=`以「${p.name}」為中心${p.accuracy?` · 定位精度約 ${Math.round(p.accuracy)} 公尺`:''}`;status(p.accuracy>300?'定位範圍較大，建議輸入附近地標提高準確度。':'已選定位置。距離以直線計算，出發前請在 Google Maps 確認營業。');render()}
function showSuggestions(items,heading){$('suggestions').hidden=false;const nodes=[e('p','suggestion-title',heading)];for(const item of items){const b=e('button','suggestion');b.type='button';b.append(e('strong','',item.name),e('span','',item.address||`${item.lat.toFixed(5)}, ${item.lon.toFixed(5)}`));b.addEventListener('click',()=>selectCenter(item));nodes.push(b)}$('suggestions').replaceChildren(...nodes)}
async function search(){const query=$('location').value.trim();if(!query){status('請輸入地標、收藏店名，或「緯度, 經度」。',true);$('location').focus();return}geoVersion++;$('geo').disabled=false;$('geo').textContent='◎ 使用目前位置';const coords=parseCoordinates(query);if(coords){selectCenter({...coords,name:query});return}const q=normalize(query);const local=[...landmarks,...data.places.map(p=>({...p,name:p.name}))].filter(p=>normalize(p.name).includes(q)).slice(0,8);const exact=landmarks.find(p=>normalize(p.name)===q||normalize(p.name).replace(/站$/,'')===q);if(exact){selectCenter(exact);return}if(local.length)showSuggestions(local,'收藏／常用地標中的位置，可直接選擇');else{$('suggestions').hidden=true;$('suggestions').replaceChildren()}const version=++searchVersion;searchController?.abort();searchController=new AbortController();const controller=searchController;const signal=controller.signal;$('find').disabled=true;status('正在查詢地標…');try{const cacheKey=q;let found=searchCache.get(cacheKey);if(!found){const delay=Math.max(0,1100-(Date.now()-lastSearch));if(delay)await new Promise(r=>setTimeout(r,delay));if(version!==searchVersion)return;lastSearch=Date.now();const term=fixAddressQuery(query).replace(/^(台北|臺北|台北市|臺北市)\s*/,'').replace(/(?:捷運)?站$/,'');const url=new URL('https://photon.komoot.io/api/');url.search=new URLSearchParams({q:term||query,limit:'8',lang:'default',lat:'25.05',lon:'121.52'});const timeout=setTimeout(()=>controller.abort(),15000);let response;try{response=await fetch(url,{signal,referrerPolicy:'strict-origin-when-cross-origin'})}finally{clearTimeout(timeout)}if(!response.ok)throw Error('service');const json=await response.json();found=(json.features||[]).filter(f=>hasCjk(f.properties?.name||f.properties?.street)).map(f=>{const pr=f.properties||{};const street=[pr.street,pr.housenumber].filter(Boolean).join('');return {name:pr.name||street||query,address:[pr.city,pr.district,street&&pr.name?street:''].filter(Boolean).join(' '),lon:f.geometry?.coordinates?.[0],lat:f.geometry?.coordinates?.[1]}}).filter(validPoint);searchCache.set(cacheKey,found)}if(version!==searchVersion)return;const seen=new Set();const combined=[...local,...found].filter(p=>{const k=`${p.name}:${p.lat.toFixed(4)}:${p.lon.toFixed(4)}`;if(seen.has(k))return false;seen.add(k);return true});if(combined.length){showSuggestions(combined,'請確認地址，再選擇你所在的地點');status('選定下方的位置後，才會更新距離。')}else status('找不到這個地標。試試較短的名稱、收藏店名，或使用目前位置。',true)}catch(err){if(version!==searchVersion)return;status(local.length?'外部地標查詢暫時不可用，仍可選擇上方收藏位置。':'地標查詢暫時不可用。可用手機定位、常用捷運站或輸入「緯度, 經度」。',true)}finally{if(version===searchVersion)$('find').disabled=false}}
function locate(){if(!navigator.geolocation){status('此瀏覽器不支援定位，請輸入地標。',true);return}searchVersion++;searchController?.abort();$('find').disabled=false;const version=++geoVersion;$('suggestions').hidden=true;$('geo').disabled=true;$('geo').textContent='定位中…';status('請允許瀏覽器使用位置，座標只在本機計算距離。');navigator.geolocation.getCurrentPosition(pos=>{if(version!==geoVersion)return;selectCenter({lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy,name:'我的目前位置'})},err=>{if(version!==geoVersion)return;$('geo').disabled=false;$('geo').textContent='◎ 使用目前位置';status(err.code===1?'定位權限未開啟。你仍可以輸入地標；要使用定位，請到瀏覽器網站權限開啟位置。':'暫時無法取得位置，請重試或輸入附近地標。',true)},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
function decide(){const result=picker.draw(matches);if(!result)return;const {place,restarted,remaining,round}=result;const panel=$('decision');panel.replaceChildren();panel.hidden=false;panel.append(e('div','eyebrow','今日推薦'),e('h2','',place.name),e('p','decision-meta',`${categoryNames(place)} · 直線 ${distanceLabel(place.distance)}`),e('p','address',place.address));const actions=e('div','decision-actions');actions.append(link('就吃這家，開啟步行導航 ↗',mapsLink(place,true)),link('確認店家與營業資訊',mapsLink(place)));panel.append(actions,e('p','pick-note',matches.length===1?'目前只有這一家符合條件。想換一家，可以放大距離或選其他分類。':`${restarted?'這輪已全部選過，重新洗牌。 ':''}第 ${round} 輪 · 還有 ${remaining} 家未選過，不滿意就再換。`));$('pick').textContent=matches.length===1?'目前只有這一家':'不滿意，換一家 ↝';$('result-status').textContent=`幫你選了 ${place.name}`;panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
let basePlaces=[],custom=[],links=[];
const WORKER='https://what-to-eat-list.pennychao11.workers.dev',LK='wte-links';
const allPlaces=()=>[...basePlaces,...custom,...links.flatMap(l=>l.places)];
function loadLinks(){try{const v=JSON.parse(localStorage.getItem(LK));return Array.isArray(v)?v.filter(l=>l&&l.url&&l.name&&Array.isArray(l.places)):[]}catch{return []}}
function saveLinks(){try{localStorage.setItem(LK,JSON.stringify(links));return true}catch{return false}}
async function fetchList(url){const r=await fetch(`${WORKER}?url=${encodeURIComponent(url)}`);const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'讀取失敗');return j}
function toPlaces(json,name){return json.places.filter(validPoint).map(p=>({...p,id:`l-${p.id}`,list:name,categories:classify(p.name)}))}
const CK='wte-custom';
function loadCustom(){try{const v=JSON.parse(localStorage.getItem(CK));return Array.isArray(v)?v.filter(p=>validPoint(p)&&p.name&&p.list&&Array.isArray(p.categories)):[]}catch{return []}}
function saveCustom(){try{localStorage.setItem(CK,JSON.stringify(custom));return true}catch{return false}}
function buildLists(){const names=[...new Set([...(data.lists||[]),...custom.map(p=>p.list),...links.map(l=>l.name)])];for(const n of [...lists])if(!names.includes(n))lists.delete(n);$('lists').replaceChildren(...names.map(name=>{const b=e('button','category-btn',`${name}（${data.places.filter(p=>p.list===name).length}）`);b.type='button';b.setAttribute('aria-pressed',String(lists.has(name)));b.addEventListener('click',()=>{if(lists.has(name))lists.delete(name);else lists.add(name);b.setAttribute('aria-pressed',String(lists.has(name)));render()});return b}))}
async function geocode(query){const wait=Math.max(0,1100-(Date.now()-lastSearch));if(wait)await new Promise(r=>setTimeout(r,wait));lastSearch=Date.now();const url=new URL('https://photon.komoot.io/api/');url.search=new URLSearchParams({q:fixAddressQuery(query),limit:'8',lang:'default',lat:'25.05',lon:'121.52'});const r=await fetch(url);if(!r.ok)throw Error('service');return ((await r.json()).features||[]).filter(f=>hasCjk(f.properties?.name||f.properties?.street)).map(f=>{const pr=f.properties||{};const street=[pr.street,pr.housenumber].filter(Boolean).join('');return {name:pr.name||street||query,address:[pr.city,pr.district,street&&pr.name?street:''].filter(Boolean).join(' '),lon:f.geometry?.coordinates?.[0],lat:f.geometry?.coordinates?.[1]}}).filter(validPoint)}
function applyAndRender(){data.places=allPlaces();buildLists();render()}
async function refreshLinks(){for(const l of [...links]){try{const j=await fetchList(l.url);l.places=toPlaces(j,l.name);l.at=Date.now();saveLinks();applyAndRender();renderMine?.()}catch{}}}
let renderMine;
function initAdd(){const dlg=$('add-dialog'),msg=t=>{$('add-msg').textContent=t};let chosen=null,cats=new Set();
const refresh=()=>{applyAndRender();renderMine()};

renderMine=function(){$('add-names').replaceChildren(...[...new Set(custom.map(p=>p.list))].map(n=>{const o=document.createElement('option');o.value=n;return o}));$('add-links').replaceChildren(...links.map(l=>{const row=e('div','mine-row');row.append(e('span','',`${l.name}（${l.places.length} 家）`));const d=e('button','secondary','移除');d.type='button';d.addEventListener('click',()=>{links=links.filter(x=>x!==l);saveLinks();refresh()});row.append(d);return row}));$('add-mine').replaceChildren(...(custom.length?custom.map(p=>{const row=e('div','mine-row');row.append(e('span','',`${p.list} · ${p.name}`));const d=e('button','secondary','刪除');d.type='button';d.addEventListener('click',()=>{custom=custom.filter(x=>x.id!==p.id);saveCustom();refresh()});row.append(d);return row}):[e('p','search-help','還沒有自己新增的店家。')]))}
$('add-cats').replaceChildren(...Object.entries(categories).filter(([k])=>!['all','uncategorized'].includes(k)).map(([k,l])=>{const b=e('button','category-btn',l);b.type='button';b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>{if(cats.has(k))cats.delete(k);else cats.add(k);b.setAttribute('aria-pressed',String(cats.has(k)))});return b}));
$('link-add').addEventListener('click',async()=>{const url=$('link-url').value.trim();let u;try{u=new URL(url)}catch{msg('請貼上 Google Maps 清單的分享連結。');return}if(links.some(l=>l.url===u.href)){msg('這份清單已經匯入了。');return}msg('匯入中…');$('link-add').disabled=true;try{const j=await fetchList(u.href);let name=j.listName||'新清單';while(allPlaces().some(p=>p.list===name))name+=' (2)';links.push({url:u.href,name,places:toPlaces(j,name),at:Date.now()});if(!saveLinks())msg('瀏覽器不允許儲存，重新整理後會消失。');else msg(`已匯入「${name}」${j.total} 家。之後每次打開網站會自動更新。`);$('link-url').value='';refresh()}catch(err){msg(`匯入失敗：${err.message}。請確認清單已設為「共用」。`)}finally{$('link-add').disabled=false}});
$('add-open').addEventListener('click',()=>{renderMine();msg('');dlg.showModal()});$('add-close').addEventListener('click',()=>dlg.close());
$('add-search').addEventListener('click',async()=>{const q=$('add-q').value.trim();if(!q){msg('請輸入店名或地址。');return}msg('查詢中…');$('add-results').replaceChildren();try{const found=await geocode(q);if(!found.length){msg('找不到，試試較短的店名，或加上路名。');return}msg('選一個正確的位置：');$('add-results').replaceChildren(...found.map(item=>{const b=e('button','suggestion');b.type='button';b.append(e('strong','',item.name),e('span','',item.address));b.addEventListener('click',()=>{chosen=item;$('add-name').value=item.name;$('add-picked').hidden=false;$('add-results').replaceChildren();msg(`已選：${item.name}（${item.address}）`)});return b}))}catch{msg('地標查詢暫時不可用，請稍後再試。')}});
$('add-save').addEventListener('click',()=>{const list=$('add-list').value.trim(),name=$('add-name').value.trim();if(!list){msg('請先填清單名稱。');$('add-list').focus();return}if(!chosen||!name){msg('請先搜尋並選一個位置。');return}const id='u-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);custom.push({id,name,address:chosen.address,lat:chosen.lat,lon:chosen.lon,categories:cats.size?[...cats]:['uncategorized'],url:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(name),list});if(!saveCustom())msg('瀏覽器不允許儲存（可能是無痕模式），重新整理後會消失。');else msg(`已加入「${list}」：${name}。可以繼續搜尋下一家。`);chosen=null;$('add-q').value='';$('add-picked').hidden=true;refresh()})}
async function init(){try{const results=await Promise.all([fetch('./data/places.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('./data/landmarks.json').then(r=>{if(!r.ok)throw Error();return r.json()})]);[data,landmarks]=results;if(!Array.isArray(data.places)||!data.places.every(p=>validPoint(p)&&Array.isArray(p.categories)))throw Error();const food=data.places.filter(p=>!p.categories.includes('excluded')&&!p.categories.includes('uncategorized')).length;const unknown=data.places.filter(p=>p.categories.includes('uncategorized')).length;$('total').textContent=data.total;$('data-note').textContent=`已匯入 ${data.total} 個收藏地點 · ${food} 筆餐飲候選 · ${unknown} 筆待分類 · ${data.total-food-unknown} 筆非餐飲不參與抽選。更新：${data.importedAt}。`;$('categories').replaceChildren(...Object.entries(categories).map(([key,label])=>{const b=e('button','category-btn',label);b.type='button';b.dataset.category=key;b.setAttribute('aria-pressed',String(key==='all'));b.addEventListener('click',()=>{if(key==='all')selected.clear();else if(selected.has(key))selected.delete(key);else selected.add(key);syncCategoryButtons();render();if(selected.has('uncategorized'))status('這些地點尚未確認是否供餐，選擇前請開啟 Google Maps 查看。')});return b}));basePlaces=data.places;custom=loadCustom();links=loadLinks();data.places=allPlaces();buildLists();initAdd();refreshLinks();$('search').addEventListener('submit',ev=>{ev.preventDefault();search()});$('location').addEventListener('input',()=>{geoVersion++;$('geo').disabled=false;$('geo').textContent='◎ 使用目前位置';searchVersion++;searchController?.abort();$('find').disabled=false;$('suggestions').hidden=true});$('geo').addEventListener('click',locate);$('radius').addEventListener('change',render);$('pick').addEventListener('click',decide);$('more').addEventListener('click',()=>{visible+=24;renderCards()});document.querySelectorAll('[data-location]').forEach(b=>b.addEventListener('click',()=>{const p=landmarks.find(p=>p.name===b.dataset.location);if(p)selectCenter(p);else{$('location').value=b.dataset.location;search()}}));$('find').disabled=false;$('geo').disabled=false;render();status('收藏已載入。選個地點，開始找吃的。')}catch{status('收藏資料載入失敗，請重新整理再試一次。',true);$('results').replaceChildren(e('div','empty','無法載入清單，請檢查網路後重新整理。'))}}
init();
